import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.nkraVhM_.js";var i=JSON.parse(`{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/introduction.md","filePath":"fr/guide/introduction.md","lastUpdated":1793173149000}`),a={name:`fr/guide/introduction.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h1><h2 id="a-propos-de-sudoku" tabindex="-1">À propos de Sudoku <a class="header-anchor" href="#a-propos-de-sudoku" aria-label="Permalink to “À propos de Sudoku”">​</a></h2><p><strong>Sudoku — Le puzzle de chiffres classique, parfaitement réalisé.</strong></p><p><img src="/screenshot-ipad-main.png" alt="Sudoku sur iPad"></p><p>Redécouvrez le puzzle de logique intemporel que vous aimez, repensé pour les appareils modernes avec des contrôles fluides, de beaux thèmes et un plaisir de jeu sans fin. Que vous soyez débutant ou expert chevronné, voici l&#39;expérience Sudoku que vous attendiez.</p><h2 id="fonctionnalites-principales" tabindex="-1">Fonctionnalités principales <a class="header-anchor" href="#fonctionnalites-principales" aria-label="Permalink to “Fonctionnalités principales”">​</a></h2><h3 id="🔢-un-jeu-authentique" tabindex="-1">🔢 <strong>Un jeu authentique</strong> <a class="header-anchor" href="#🔢-un-jeu-authentique" aria-label="Permalink to “🔢 Un jeu authentique”">​</a></h3><p>Fidèle aux règles classiques : remplissez une grille 9×9 de sorte que chaque ligne, chaque colonne et chaque bloc 3×3 contienne les chiffres de 1 à 9 exactement une fois. Touchez pour placer les chiffres, utilisez les notes au crayon pour les candidats et laissez la logique vous guider vers la solution.</p><h3 id="🎯-5-niveaux-de-difficulte" tabindex="-1">🎯 <strong>5 niveaux de difficulté</strong> <a class="header-anchor" href="#🎯-5-niveaux-de-difficulte" aria-label="Permalink to “🎯 5 niveaux de difficulté”">​</a></h3><p>Cinq niveaux de difficulté soigneusement calibrés, avec un nombre de cases préremplies différent :</p><table tabindex="0"><thead><tr><th>Niveau</th><th>Cases préremplies</th><th>Description</th></tr></thead><tbody><tr><td>Facile</td><td>45</td><td>Idéal pour les débutants et les parties rapides</td></tr><tr><td>Moyen</td><td>36</td><td>Un défi équilibré pour les joueurs occasionnels</td></tr><tr><td>Difficile</td><td>31</td><td>Nécessite des techniques de déduction logique</td></tr><tr><td>Expert</td><td>27</td><td>Pour les solveurs expérimentés en quête d&#39;un vrai test</td></tr><tr><td>Maître</td><td>24</td><td>Le défi ultime — réservé aux plus courageux</td></tr></tbody></table><p>Chaque grille est générée de manière unique : deux parties ne sont jamais identiques.</p><h3 id="📱-application-universelle" tabindex="-1">📱 <strong>Application universelle</strong> <a class="header-anchor" href="#📱-application-universelle" aria-label="Permalink to “📱 Application universelle”">​</a></h3><p>Un seul achat fonctionne sur iPhone, iPad et Mac. Des contrôles natifs pour chaque plateforme : gestes tactiles sur iOS, souris et clavier sur Mac. Votre progression se synchronise via iCloud sur tous vos appareils.</p><p><img src="/screenshot-iphone-main.png" alt="Sudoku sur iPhone"></p><p><img src="/screenshot-mac-difficulty.png" alt="Sudoku sur Mac"></p><h3 id="💡-indices-et-notes" tabindex="-1">💡 <strong>Indices et notes</strong> <a class="header-anchor" href="#💡-indices-et-notes" aria-label="Permalink to “💡 Indices et notes”">​</a></h3><ul><li><strong>Indice</strong> : bloqué ? Obtenez un indice qui révèle une case correcte sans gâcher toute la grille.</li><li><strong>Crayon (notes)</strong> : activez le mode crayon pour noter les chiffres candidats dans les cases vides. Les notes au crayon des cases voisines (même ligne, même colonne ou même bloc) s&#39;effacent automatiquement lorsque vous placez un chiffre.</li><li><strong>Vérification des erreurs</strong> : mise en évidence facultative des saisies incorrectes, pour apprendre de ses erreurs.</li><li><strong>Annulation</strong> : annulation complète prise en charge — reprenez n&#39;importe quel coup, à tout moment.</li></ul><h3 id="🏆-defi-quotidien" tabindex="-1">🏆 <strong>Défi quotidien</strong> <a class="header-anchor" href="#🏆-defi-quotidien" aria-label="Permalink to “🏆 Défi quotidien”">​</a></h3><p>Une nouvelle grille chaque jour, au niveau de difficulté Maître. Construisez une série et suivez votre progression quotidienne dans la vue calendrier des statistiques.</p><h3 id="📊-statistiques" tabindex="-1">📊 <strong>Statistiques</strong> <a class="header-anchor" href="#📊-statistiques" aria-label="Permalink to “📊 Statistiques”">​</a></h3><p>Suivez vos performances : nombre total de parties jouées, taux de réussite, série actuelle, meilleure série, et des bilans par niveau de difficulté incluant les meilleurs temps et les moyennes. Synchronisées via iCloud.</p><h3 id="🎨-8-themes-magnifiques" tabindex="-1">🎨 <strong>8 thèmes magnifiques</strong> <a class="header-anchor" href="#🎨-8-themes-magnifiques" aria-label="Permalink to “🎨 8 thèmes magnifiques”">​</a></h3><p>Personnalisez votre plateau avec huit thèmes de couleurs façonnés avec soin : Classic, Midnight, Paper, Forest, Ocean, Sunset, Lavender et Rose. Chaque thème offre une expérience visuelle distinctive tout en conservant une excellente lisibilité.</p><h3 id="☁️-synchronisation-icloud" tabindex="-1">☁️ <strong>Synchronisation iCloud</strong> <a class="header-anchor" href="#☁️-synchronisation-icloud" aria-label="Permalink to “☁️ Synchronisation iCloud”">​</a></h3><p>Vos réglages, vos statistiques, vos parties sauvegardées et votre progression dans le défi quotidien se synchronisent automatiquement sur tous vos appareils Apple via CloudKit. Commencez une partie sur votre iPhone, poursuivez-la sur votre Mac.</p><h3 id="🎮-game-center" tabindex="-1">🎮 <strong>Game Center</strong> <a class="header-anchor" href="#🎮-game-center" aria-label="Permalink to “🎮 Game Center”">​</a></h3><p>Affrontez les autres sur les classements avec vos meilleurs temps de résolution et débloquez des succès : First Solve, Easy Clear, Medium Clear, Hard Clear, Expert Clear, Master Clear et Flawless (terminer sans indice ni erreur).</p><h3 id="🔇-une-interface-epuree-sans-publicite" tabindex="-1">🔇 <strong>Une interface épurée, sans publicité</strong> <a class="header-anchor" href="#🔇-une-interface-epuree-sans-publicite" aria-label="Permalink to “🔇 Une interface épurée, sans publicité”">​</a></h3><p>Aucune interruption, aucune fenêtre surgissante, aucune publicité, aucun achat intégré. Rien que du jeu de puzzle pur et concentré.</p><h3 id="🌍-25-langues" tabindex="-1">🌍 <strong>25 langues</strong> <a class="header-anchor" href="#🌍-25-langues" aria-label="Permalink to “🌍 25 langues”">​</a></h3><p>Changez de langue à tout moment dans les réglages, sans redémarrer l&#39;application. Langues prises en charge : anglais, chinois (simplifié et traditionnel), japonais, coréen, français, allemand, espagnol, italien, russe, portugais, néerlandais, vietnamien, thaï, hindi, turc, grec, finnois, norvégien, danois, hongrois, indonésien, malais, ukrainien et allemand (Suisse).</p><h3 id="🔊-effets-sonores" tabindex="-1">🔊 <strong>Effets sonores</strong> <a class="header-anchor" href="#🔊-effets-sonores" aria-label="Permalink to “🔊 Effets sonores”">​</a></h3><p>Des effets sonores discrets pour le placement des chiffres, les indices, les erreurs et la victoire — à activer ou désactiver dans les réglages.</p><h3 id="🖨️-imprimer-des-grilles" tabindex="-1">🖨️ <strong>Imprimer des grilles</strong> <a class="header-anchor" href="#🖨️-imprimer-des-grilles" aria-label="Permalink to “🖨️ Imprimer des grilles”">​</a></h3><p>Imprimez des grilles directement depuis l&#39;application Mac, avec choix du niveau de difficulté et solutions facultatives. Parfait pour résoudre hors ligne avec un stylo et du papier.</p><h2 id="configuration-requise" tabindex="-1">Configuration requise <a class="header-anchor" href="#configuration-requise" aria-label="Permalink to “Configuration requise”">​</a></h2><ul><li><strong>iPhone/iPad</strong> : iOS/iPadOS 16.0 ou version ultérieure</li><li><strong>Mac</strong> : macOS 15.0 (Sequoia) ou version ultérieure (Apple Silicon)</li><li><strong>Stockage</strong> : ~50 Mo</li></ul><h2 id="confidentialite" tabindex="-1">Confidentialité <a class="header-anchor" href="#confidentialite" aria-label="Permalink to “Confidentialité”">​</a></h2><p>Le cœur du jeu Sudoku fonctionne hors ligne en priorité. Toutes les données de jeu sont stockées localement et synchronisées uniquement vers votre compte iCloud personnel. Aucune publicité, aucune analyse, aucun suivi par des tiers. Les seules fonctions réseau sont la synchronisation iCloud, Game Center et une section facultative « Plus d&#39;apps » dans les réglages.</p><p>Consultez la <a href="/fr/guide/privacy.html">politique de confidentialité</a> pour plus de détails.</p><h2 id="pour-commencer" tabindex="-1">Pour commencer <a class="header-anchor" href="#pour-commencer" aria-label="Permalink to “Pour commencer”">​</a></h2><p>Si vous découvrez Sudoku, commencez par le <a href="/fr/guide/installation.html">guide d&#39;installation</a> pour installer l&#39;application sur votre appareil.</p>`,43)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};